        final bool isDark = ThemeController.instance.isDark;
        return Material(
          color: Colors.transparent,
          child: InkWell(
            borderRadius: BorderRadius.circular(999),
            onTap: () => ThemeController.instance.setThemeMode(
              isDark ? ThemeMode.light : ThemeMode.dark,
